import type { ApiSection } from "./api-reference-types";

/**
 * The open API reference, rendered to /api.html (Johan 8/10). One entry per
 * name in `src/entries/public-surface.snapshot.json` — the gate
 * `src/gates/api-reference-covers-surface.test.ts` holds the two together.
 * Written from the source and its tests; when a name's behaviour changes, its
 * words here change in the same commit.
 */
export const API_SECTIONS: ApiSection[] = [
  {
    id: "guide-preview",
    heading: {"sv": "<guide-preview> — visaren", "en": "<guide-preview> — the viewer"},
    intro: {"sv": "Elementet besökarens sida laddar. Det kör en guide: ett steg i taget eller en sida i taget, med svaren kvar när besökaren går tillbaka.", "en": "The element a visitor's page loads. It runs a guide, one step or one page at a time, keeping the answers when the visitor goes back."},
    entries: [
      { name: "active-locale", kind: "attribute", signature: "active-locale=\"sv\"", values: "\"sv\" | \"en\"", text: { sv: "Språket guiden visas i, som en språkkod. Attributet går via egenskapen activeLocale, så både texterna och motorns svar byter språk; tas attributet bort faller visaren tillbaka på standardspråket. Läses också när grafen laddas, så första ritningen blir på rätt språk.", en: "The language to show the guide in, as a locale code. Setting the attribute goes through the activeLocale property, so both the rendered text and the engine switch; removing it falls back to the default source locale. It is also read when the graph loads, so the first paint is already in the right language." } },
      { name: "answer-display", kind: "attribute", signature: "answer-display=\"trail\"", values: "\"trail\" | \"history\"", text: { sv: "Visar besökarens tidigare svar ovanför steget. \"trail\" ger en lista med fråga och svar, där svaret visas som besökaren ser det (med enhet); \"history\" ger en enklare lista med frågan och det valda alternativets text. Utan attributet, eller med annat värde, visas ingen lista.", en: "Shows the visitor's earlier answers above the current step. \"trail\" lists each question with the answer as displayed (unit included); \"history\" is a plainer list of the question and the chosen option's label. Absent or any other value: no list." } },
      { name: "example-files", kind: "attribute", signature: "example-files", text: { sv: "Boolesk. När värden sätter attributet får en filfråga vars steg har ett exempelfoto en knapp bredvid filväljaren som hämtar exempelfotot och bifogar det. Utan attributet visas ingen sådan knapp, även om guiden har ett exempelfoto. Avsett för demo- och provsidor.", en: "Boolean. When present, a file field whose step carries an example photo gets a button beside the file picker that fetches the example and attaches it. Without it no such button is drawn, even if the guide has an example photo. Meant for demo and try-it pages." } },
      { name: "proving", kind: "attribute", signature: "proving", text: { sv: "Boolesk. Markerar en provkörning i editorn: filfält och kartfrågor får ersättningar (en provbild, en ritad karta) i stället för riktig filväljare, dolda villkorsfält visas inte, och händelsen guide-progress skickas inte. Sätts av editorn; en värd ska normalt inte sätta den på en publicerad sida.", en: "Boolean. Marks a trial run inside the editor: file fields and map questions get stand-ins (a sample picture, a drawn map) instead of the real picker, hidden conditional fields stay hidden, and no guide-progress event is fired. Set by the editor; a host should not normally set it on a published page." } },
      { name: "activeLocale", kind: "property", signature: "activeLocale: string (write-only)", text: { sv: "Sätter språket guiden visas i och meddelar motorn, så att även svar och mallar följer med; ritar om direkt. Samma sak som attributet active-locale, som går via den här egenskapen. Har ingen getter – att läsa den ger undefined.", en: "Sets the language the guide is shown in and tells the engine, so answers and templates follow; re-renders at once. Same effect as the active-locale attribute, which routes through this property. It has no getter, so reading it returns undefined." } },
      { name: "clear", kind: "method", signature: "clear(message?: string): void", text: { sv: "Tar bort guiden ur visaren och visar ett tomt läge med meddelandet. Standardtexten är \"Ingen guide har valts.\" (svenska, inte översatt). Sätt graph igen för att visa en guide.", en: "Removes the guide from the viewer and shows an empty state with the given message. The default text is \"Ingen guide har valts.\" (Swedish, not localised). Set graph again to show a guide." } },
      { name: "getAnswers", kind: "method", signature: "getAnswers(): Answers", text: { sv: "Besökarens svar hittills i körningen, som ett objekt med variabelnamn som nycklar. Bara svar på den väg besökaren faktiskt gått räknas. Tomt objekt om ingen guide är laddad. Filer finns inte här – använd getFiles().", en: "The visitor's answers so far, as an object keyed by variable name. Only answers on the path the visitor actually took are included. Returns an empty object when no guide is loaded. Files are not in it; use getFiles()." } },
      { name: "getCurrentNodeId", kind: "method", signature: "getCurrentNodeId(): string | null", text: { sv: "Id:t för steget besökaren står på, eller null om ingen guide är laddad. Spara det tillsammans med getAnswers() och lämna tillbaka båda via given för att låta besökaren fortsätta senare.", en: "The id of the step the visitor is on, or null when no guide is loaded. Save it alongside getAnswers() and hand both back through given to let the visitor resume later." } },
      { name: "getFiles", kind: "method", signature: "getFiles(): { fieldId: string; variableName: string; file: File }[]", text: { sv: "De filer besökaren valt i guidens filfält, med fältets id och variabelnamn. Filerna skickas ingenstans av visaren; värden hämtar dem när det är dags att skicka in. Provbilder från en provkörning kommer aldrig med.", en: "The files the visitor has chosen in the guide's file fields, with each field's id and variable name. The viewer sends them nowhere; the host collects them when it is time to submit. Stand-ins from a trial run are never included." } },
      { name: "getFormData", kind: "method", signature: "getFormData(): FormData", text: { sv: "Alla svar och filer kodade som ett webbläsarformulär, klart att skicka med fetch som multipart. En filvariabel kommer med en gång, som filen; svar från en upprepad sida blir namn[index].fält; en fil utan variabelnamn läggs under file-<fältets id>.", en: "Every answer and file encoded the way a browser encodes a form, ready to post with fetch as multipart. A file variable appears once, as the file; answers from a repeating page become name[index].field; a file with no variable name goes under file-<field id>." } },
      { name: "getOutput", kind: "method", signature: "getOutput(): EmailResultOutput | null", text: { sv: "Om steget besökaren står på har ett utdata (i dag e-postresultatet) får värden mottagare, ämne och brödtext, både som mall och med svaren ifyllda, plus vilka variabler som saknades. Annars null.", en: "If the current step produces output (today the email result), returns the recipient, subject and body, both as the template and with answers filled in, plus any variables that were missing. Otherwise null." } },
      { name: "getStepNumber", kind: "method", signature: "getStepNumber(): number", text: { sv: "Vilket steg i ordningen besökaren står på, enligt motorn. Ger 1 om ingen guide är laddad. Finns främst för editorns andra spegling av samma körning; visaren visar själv stegnumret.", en: "Which step in sequence the visitor is on, as counted by the engine. Returns 1 when no guide is loaded. Mainly for the editor's second mirror of the same run; the viewer already shows the step number itself." } },
      { name: "getTraversedConnectionIds", kind: "method", signature: "getTraversedConnectionIds(): string[]", text: { sv: "Id:n för de kopplingar i guiden som körningen passerat, i ordning. Tom lista om ingen guide är laddad. Används främst av editorn för att markera vägen på arbetsytan.", en: "The ids of the guide's connections the run has passed through, in order. Empty when no guide is loaded. Mainly used by the editor to highlight the route on the canvas." } },
      { name: "given", kind: "property", signature: "given: GivenAnswers | null   // { answers: Answers; nodeId?: string | null }", text: { sv: "Svar värden redan känner till, till exempel namn från en inloggning eller en sparad körning. Värdena fyller fälten men låses inte – besökaren kan ändra dem och de valideras som vanligt. nodeId öppnar guiden på det steget vid laddning; kan sättas före eller efter graph och gäller även efter Börja om.", en: "Answers the host already knows, such as a name from a login or a saved run. They fill the fields but nothing is locked: the visitor can change them and they are validated as if typed. nodeId opens the guide on that step at load; can be set before or after graph and survives a restart." } },
      { name: "graph", kind: "property", signature: "graph: GraphData | null", text: { sv: "Guiden som ska visas, i standardformat. Äldre format lyfts till dagens vid inläsning; en guide från en nyare version vägras och visaren säger det i stället för att rita en halv sida. Att läsa egenskapen ger en kopia, eller null om ingen guide är laddad.", en: "The guide to show, in the standard format. Older formats are migrated on load; a guide from a newer version is refused and the viewer says so instead of drawing a broken page. Reading returns a copy, or null when nothing is loaded." } },
      { name: "mirror", kind: "method", signature: "mirror(source: GuidePreview | null): void", text: { sv: "Låter den här visaren rita samma körning som en annan visare – samma motor, inte en kopia – så att Nästa i den ena är Nästa i den andra. null kopplar loss den. Intern koppling för editorns arbetsyta; en värd behöver den sällan.", en: "Makes this viewer draw the same run as another one, sharing its engine rather than a copy, so Next in one is Next in the other. null detaches it. Internal wiring for the editor's canvas; a host rarely needs it." } },
      { name: "previous", kind: "method", signature: "previous(): void", text: { sv: "Går ett steg bakåt, samma som besökarens Tillbaka-knapp, och skickar preview-node-changed. Gör ingenting om det inte finns något steg bakåt.", en: "Goes back one step, as the visitor's Back button does, and fires preview-node-changed. Does nothing if there is no step to go back to." } },
      { name: "refresh", kind: "method", signature: "refresh(): void", text: { sv: "Ritar om visaren från motorn och släpper ett visat utkast. För en speglad visare vars motor flyttats av någon annan; intern koppling för editorn.", en: "Re-renders from the engine and drops any shown draft. For a mirrored viewer whose engine someone else moved; internal wiring for the editor." } },
      { name: "restart", kind: "method", signature: "restart(): void", text: { sv: "Börjar om guiden från första steget som ett nytt ärende. Värdens given-svar fylls i igen men steget i given används inte. Skickar preview-node-changed och guide-progress med \"restart\".", en: "Starts the guide over from the first step as a new case. The host's given answers are filled in again, but the step in given is not reused. Fires preview-node-changed and guide-progress with \"restart\"." } },
      { name: "reviewDeclarationEnabled", kind: "property", signature: "reviewDeclarationEnabled: boolean", text: { sv: "Om granskningssteget ska visa redovisningen av vad beskedet byggde på under besökarens svar. Standard true; sätt false på sidor där det inte finns något beslut att redovisa, till exempel en intresseanmälan.", en: "Whether the review step shows the declaration of what the decision rests on beneath the visitor's answers. Defaults to true; set false on pages where there is no decision to account for, such as an expression of interest." } },
      { name: "routeAnalysisEnabled", kind: "property", signature: "routeAnalysisEnabled: boolean", text: { sv: "Om visaren visar vägarna: vart ett steg leder på kort som regler och tjänsteanrop, och vilka vägar som når ett resultat i kompakt läge. Standard true. Det är kort en besökare sällan stannar på; i praktiken sätter editorn den efter sina funktioner.", en: "Whether the viewer shows the routes: where a step leads on cards such as rules and service calls, and which paths reach a result in compact mode. Defaults to true. These are cards a visitor seldom stops on; in practice the editor sets it from its capabilities." } },
      { name: "setTheme", kind: "method", signature: "setTheme(theme: \"light\" | \"dark\" | null): void", text: { sv: "Sätter visarens tema, samma som egenskapen theme. null låter operativsystemets inställning avgöra.", en: "Sets the viewer's theme, same as the theme property. null hands the choice back to the operating system setting." } },
      { name: "showDraft", kind: "method", signature: "showDraft(values: Answers): void", text: { sv: "Visar osparade värden i sidans fält – vad den andra speglade visaren håller på att skriva – utan att spara dem. Intern koppling för editorns spegling; en värd behöver den sällan.", en: "Shows unsaved values in the page's fields, namely what the other mirrored viewer is typing, without storing them. Internal wiring for the editor's mirroring; a host rarely needs it." } },
      { name: "showNode", kind: "method", signature: "showNode(nodeId: string): boolean", text: { sv: "Hoppar direkt till ett steg och ritar det. Är id:t ett fält på en sida visas sidan med fältet markerat. Ger true om steget kunde visas. Används av editorn för att visa vald nod; skickar ingen händelse.", en: "Jumps straight to a step and draws it. If the id is a field on a page, the page is shown with that field highlighted. Returns true if the step could be shown. Used by the editor to show the selected node; fires no event." } },
      { name: "shownAnswers", kind: "property", signature: "shownAnswers: Answers (write-only)", text: { sv: "Fyller i svar för att rita ett redan besvarat steg, till exempel som bild på editorns arbetsyta. Avgör ingenting i körningen. Intern koppling för editorn; har ingen getter.", en: "Seeds answers so an already-answered step can be drawn with them, such as a picture on the editor's canvas. Decides nothing in the run. Internal wiring for the editor; it has no getter." } },
      { name: "theme", kind: "property", signature: "theme: \"light\" | \"dark\" | null", values: "\"light\" | \"dark\" | null", text: { sv: "Ljust eller mörkt tema för visaren; null följer operativsystemet. Sätts som data-fw-theme på elementet, inte på dokumentet, så värdens sida runt omkring inte färgas om.", en: "Light or dark theme for the viewer; null follows the operating system. Written as data-fw-theme on the element, not the document, so the host's page around it is not recoloured." } },
      { name: "unmatchedGiven", kind: "method", signature: "unmatchedGiven(): string[]", text: { sv: "De namn i given som ingen nod i guiden deklarerar som variabel. Värdena behålls ändå, men listan förklarar varför ett fält förblev tomt. Samma namn loggas också med console.info.", en: "The names in given that no node in the guide declares as a variable. Those values are kept anyway, but the list explains why a field stayed empty. The same names are also logged with console.info." } },
      { name: "variableInspectorEnabled", kind: "property", signature: "variableInspectorEnabled: boolean", text: { sv: "Om visaren ska visa en utfällbar lista med variablernas aktuella värden under guiden. Standard true; en värd stänger normalt av den på en publicerad sida.", en: "Whether the viewer shows a collapsible list of the variables' current values below the guide. Defaults to true; a host would normally turn it off on a published page." } },
    ],
  },
  {
    id: "guide-editor",
    heading: {"sv": "<guide-editor> — editorn", "en": "<guide-editor> — the editor"},
    intro: {"sv": "Elementet redaktören bygger guiden i. Värden bestämmer vad som erbjuds, sparar det editorn lämnar ifrån sig och lyssnar på dess händelser.", "en": "The element the person editing builds the guide in. The host decides what it offers, stores what it hands over and listens to its events."},
    entries: [
      { name: "active-locale", kind: "attribute", signature: "active-locale=\"<language code>\"", values: "\"sv\" | \"en\"", text: { sv: "Vilket av guidens språk redigeringen ska börja i. Gäller bara om guiden erbjuder språket; annars hamnar en översättare i första språket som inte är källspråket och alla andra i källspråket. Det är en vy och sparas aldrig i guiden; aktuellt språk läses med contentLocale.", en: "Which of the guide's languages editing starts in. It only applies if the guide offers that language; otherwise a translator lands in the first non-source language and everyone else in the source language. It is a view and is never stored in the guide; read the current language with contentLocale." } },
      { name: "editor-locale", kind: "attribute", signature: "editor-locale=\"sv\" | \"en\"", values: "\"sv\" | \"en\"", text: { sv: "Språket i själva verktyget: palett, panel, menyer och meddelanden. Det är skilt från guidens innehållsspråk (active-locale). Editorn har texter på svenska och engelska.", en: "The language of the tool itself: palette, panel, menus and messages. It is separate from the guide's content language (active-locale). The editor ships strings in Swedish and English." } },
      { name: "feature-level", kind: "attribute", signature: "feature-level=\"basic\" | \"advanced\" | \"service\"", values: "\"basic\" | \"advanced\" | \"service\"", text: { sv: "Hur mycket av editorn redaktören får: vilka nodtyper och funktioner som erbjuds. Ignoreras när attributet modules är satt. Speglas av egenskapen featureLevel.", en: "How much of the editor the person editing gets: which node types and features are offered. Ignored while the modules attribute is set. Mirrored by the featureLevel property." } },
      { name: "get-started-href", kind: "attribute", signature: "get-started-href=\"<url>\"", text: { sv: "Adress till värdens egen kom-igång-sida. Med attributet visas posten Kom igång under Hjälp och leder dit; utan det finns posten inte alls.", en: "Address of the host's own getting-started page. With it, Help offers a Getting started item that leads there; without it the item is not shown." } },
      { name: "mode", kind: "attribute", signature: "mode=\"administrator\" | \"edit\" | \"translator\" | \"readonly\"", values: "\"administrator\" | \"edit\" | \"translator\" | \"readonly\"", text: { sv: "Vad redaktören får ändra. Utan attributet, eller med okänt värde, är editorn låst i läsläge: värden måste uttryckligen ge rättigheter. Läget är en vy och inget skydd — behörigheter är värdens sak. Sätter egenskapen mode.", en: "What the person editing may change. Without the attribute, or with an unknown value, the editor is locked read-only: the host has to grant capability explicitly. The mode is a view, not protection — permissions are the host's job. Sets the mode property." } },
      { name: "mode-notice", kind: "attribute", signature: "mode-notice=\"off\"", values: "\"off\"", text: { sv: "Med \"off\" göms panelens ruta som förklarar varför fälten är låsta. För en värd som själv säger det, t.ex. i en egen rad ovanför editorn. Läget påverkas inte.", en: "With \"off\", the panel's box explaining why fields are locked is hidden. For a host that says so itself, for example in its own bar above the editor. The mode is unaffected." } },
      { name: "modules", kind: "attribute", signature: "modules=\"<module ids, space- or comma-separated>\"", values: "\"logic\" | \"content\" | \"fields\" | \"host-services\" | \"pages\" | \"submission\"", text: { sv: "Bygger editorns funktioner ur moduler i stället för en nivå: grunden (flerval, regler, variabler, import/export) är alltid på och varje modul lägger till mer. Ett tomt attribut ger bara grunden; utan attribut styr feature-level. Menyn visar bara moduler som har en registrerad nodtyp, så submission syns först när PRO är laddat.", en: "Builds the editor's capabilities from modules instead of a level: the core (multiple choice, rules, variables, import/export) is always on and each module adds more. An empty attribute gives just the core; with no attribute, feature-level decides. The menu only lists modules backed by a registered node type, so submission appears only once PRO is loaded." } },
      { name: "palette-open", kind: "attribute", signature: "palette-open (boolean)", text: { sv: "Om hela nodpaletten är utfälld. Värden sätter det före första ritningen och hör palette-open-changed med { open } när redaktören ändrar det; biblioteket sparar ingenting. Speglas av egenskapen paletteOpen.", en: "Whether the full node palette is expanded. The host sets it before first paint and hears palette-open-changed with { open } when the person editing changes it; the library stores nothing. Mirrored by the paletteOpen property." } },
      { name: "palette-search", kind: "attribute", signature: "palette-search=\"off\"", values: "\"off\"", text: { sv: "Med \"off\" har nodpaletten ingen sökruta (Sök nod). Värdens val när editorn sätts upp.", en: "With \"off\", the node palette has no search field (Search node). The host's choice when setting the editor up." } },
      { name: "panel-open", kind: "attribute", signature: "panel-open (boolean)", text: { sv: "Om sidopanelen (Egenskaper/Förhandsgranskning) är utfälld över canvasen. Redaktörens egna öppningar och stängningar meddelas med panel-open-changed och { open }; värden avgör om det ska kommas ihåg och sätter det före första ritningen. Speglas av egenskapen panelOpen.", en: "Whether the side panel (Properties/Preview) is open over the canvas. The person editing opening or folding it is announced with panel-open-changed and { open }; the host decides whether to remember it and sets it before first paint. Mirrored by the panelOpen property." } },
      { name: "panel-width", kind: "attribute", signature: "panel-width=\"<px>\"", text: { sv: "Sidopanelens bredd i pixlar. När redaktören drar i kanten kommer panel-width-changed med { width } (null efter återställning), och värden kan spara värdet och lämna tillbaka det här. Speglas av egenskapen panelWidth.", en: "The side panel's width in pixels. When the person editing drags its edge, panel-width-changed fires with { width } (null after a reset), and the host can store the value and hand it back here. Mirrored by the panelWidth property." } },
      { name: "theme", kind: "attribute", signature: "theme=\"light\" | \"dark\"", values: "\"light\" | \"dark\"", text: { sv: "Ljust eller mörkt tema för editorn. Sätts på elementet, inte på dokumentet, så värdens sida runt omkring påverkas inte. Sätter egenskapen theme.", en: "Light or dark theme for the editor. It is applied to the element, not the document, so the host page around it is unaffected. Sets the theme property." } },
      { name: "addCustomNodeType", kind: "method", signature: "addCustomNodeType(spec: NodeTemplate): void", text: { sv: "Lägger till en nodmall i biblioteket, eller ersätter den om nyckeln (spec.type) redan finns. Paletten uppdateras, en bekräftelse visas, och node-templates-changed skickas med hela listan så värden kan spara. Biblioteket delas av alla editorer på sidan.", en: "Adds a node template to the library, or replaces it if the key (spec.type) already exists. The palette refreshes, a confirmation toast is shown, and node-templates-changed fires with the whole list so the host can save it. The library is shared by every editor on the page." } },
      { name: "buildId", kind: "property", signature: "readonly buildId: string", text: { sv: "Vilket bygge av editorn som körs: commit, om det fanns ocommittade ändringar, och tid. Till för felsökning, t.ex. på en värds supportsida för att se vad en enhet faktiskt kör.", en: "Which build of the editor is running: commit, whether there were uncommitted changes, and time. Meant for troubleshooting, such as a host's support page showing what a device is actually running." } },
      { name: "capabilities", kind: "property", signature: "capabilities: EditorCapabilities  (setter takes Partial<EditorCapabilities>)", text: { sv: "Läser de funktioner som faktiskt gäller (en kopia). Att sätta värdet lägger enskilda av- eller påslag ovanpå det som feature-level eller modules ger; varje ny tilldelning ersätter de tidigare påslagen.", en: "Reads the capabilities actually in effect (a copy). Setting it layers individual on/off overrides on top of what feature-level or modules give; each assignment replaces the previous overrides." } },
      { name: "contentLocale", kind: "property", signature: "readonly contentLocale: string", text: { sv: "Det språk av guidens innehåll som redigeras just nu, t.ex. efter att redaktören bytt språk i verktygsraden. Startvärdet styrs av active-locale och läget.", en: "The language of the guide's content currently being edited, for example after the person editing switched language in the toolbar. Its starting value comes from active-locale and the mode." } },
      { name: "featureLevel", kind: "property", signature: "featureLevel: \"basic\" | \"advanced\" | \"service\"", values: "\"basic\" | \"advanced\" | \"service\"", text: { sv: "Samma sak som attributet feature-level: att sätta egenskapen skriver attributet. Läser den nivå som är satt, även när modules styr i stället.", en: "Same as the feature-level attribute: setting the property writes the attribute. Reads the level that is set, even when modules is in control instead." } },
      { name: "getData", kind: "method", signature: "getData(): GraphData", text: { sv: "Guiden som den ser ut nu, i standardformat och redo att sparas: noder och kopplingar från canvasen, guidens inställningar, de nodmallar guiden använder, och formatversionen stämplad. Det här är vad värden ska lagra.", en: "The guide as it stands, in the standard format and ready to store: nodes and connections from the canvas, the guide's settings, the node templates it uses, and the format version stamped on. This is what the host should save." } },
      { name: "graph", kind: "property", signature: "graph: GraphData", text: { sv: "Att sätta graph öppnar en guide: den migreras till aktuellt format, ångra-historiken och markeringen nollställs, och en guide i ett format som inte stöds avvisas med ett felmeddelande i editorn. Att läsa den ger samma som getData().", en: "Setting graph opens a guide: it is migrated to the current format, the undo history and selection are reset, and a guide in an unsupported format is refused with an error message in the editor. Reading it returns the same as getData()." } },
      { name: "mode", kind: "property", signature: "mode: \"administrator\" | \"edit\" | \"translator\" | \"readonly\"", values: "\"administrator\" | \"edit\" | \"translator\" | \"readonly\"", text: { sv: "Vad redaktören får ändra; samma värden som attributet mode, som sätter den här egenskapen. Egenskapen skriver inte tillbaka attributet, och den kontrollerar inte värdet — använd ett av de fyra.", en: "What the person editing may change; same values as the mode attribute, which sets this property. The property does not write the attribute back, and it does not validate the value — use one of the four." } },
      { name: "modules", kind: "property", signature: "modules: string[] | null", values: "null", text: { sv: "Samma sak som attributet modules: en lista skrivs som mellanslagsseparerat attribut, null tar bort attributet. Läser de giltiga modul-id:na efter tolkning (alias upplösta, okända bortfiltrerade), eller null.", en: "Same as the modules attribute: a list is written as a space-separated attribute, null removes the attribute. Reads the valid module ids after parsing (aliases resolved, unknown ones dropped), or null." } },
      { name: "nodeTemplates", kind: "property", signature: "nodeTemplates: NodeTemplate[]  (setter accepts unknown)", text: { sv: "Värdens nodmallar. Att sätta listan ersätter alla icke inbyggda mallar; ogiltiga poster hoppas över och de inbyggda finns kvar. Att läsa ger redaktörens egna mallar utan de inbyggda. Biblioteket sparar ingenting — ändringar i editorn meddelas med node-templates-changed.", en: "The host's node templates. Setting the list replaces all non-built-in templates; invalid entries are skipped and the built-ins stay. Reading returns the editor-made templates without the built-ins. The library stores nothing — changes made in the editor are announced with node-templates-changed." } },
      { name: "paletteOpen", kind: "property", signature: "paletteOpen: boolean", text: { sv: "Om hela nodpaletten är utfälld; att sätta den slår på eller av attributet palette-open.", en: "Whether the full node palette is expanded; setting it toggles the palette-open attribute." } },
      { name: "panelOpen", kind: "property", signature: "panelOpen: boolean", text: { sv: "Om sidopanelen är utfälld; att sätta den slår på eller av attributet panel-open. Det är en vy, ingen ändring i guiden och inget ångra-steg.", en: "Whether the side panel is open; setting it toggles the panel-open attribute. It is a view, not a change to the guide and not an undo step." } },
      { name: "panelWidth", kind: "property", signature: "panelWidth: number | null", text: { sv: "Sidopanelens begärda bredd i pixlar; att sätta den skriver attributet panel-width, null tar bort det och ger standardbredden. Läser det värde som begärts, inte den bredd som faktiskt ritas inom gränserna.", en: "The side panel's requested width in pixels; setting it writes the panel-width attribute, and null removes it for the default width. Reads the requested value, not the width actually drawn within the bounds." } },
      { name: "redo", kind: "method", signature: "redo(): void", text: { sv: "Gör om det senast ångrade steget, om det finns något. Samma som redaktörens Gör om.", en: "Redoes the last undone step, if there is one. Same as the person editing choosing Redo." } },
      { name: "refreshGraph", kind: "method", signature: "refreshGraph(value: GraphData): void", text: { sv: "Laddar en nyare version av samma guide utan att flytta vyn: den som tittar behåller sin panorering och zoom. Till för t.ex. ett läsfönster som följer en kollegas arbete. Som att sätta graph i övrigt, så ångra-historiken nollställs.", en: "Loads a newer version of the same guide without moving the view: whoever is watching keeps their pan and zoom. Meant for e.g. a read-only window following a colleague's work. Otherwise like setting graph, so the undo history is reset." } },
      { name: "removeCustomNodeType", kind: "method", signature: "removeCustomNodeType(type: string): void", text: { sv: "Tar bort en nodmall ur biblioteket (inbyggda mallar kan inte tas bort). Noder som skapats ur den fungerar som förut men bär bastypens namn. Skickar node-templates-changed.", en: "Removes a node template from the library (built-in templates cannot be removed). Nodes created from it keep working but carry the base type's name. Fires node-templates-changed." } },
      { name: "replaceGraph", kind: "method", signature: "replaceGraph(value: GraphData, reason: GraphChangedDetail[\"reason\"]): void", values: "\"node-moved\" | \"node-nudged\" | \"node-created\" | \"node-removed\" | \"start-node-changed\" | \"node-updated\" | \"node-template-changed\" | \"guide-updated\" | \"graph-imported\" | \"form-skeleton-added\" | \"graph-reset\" | \"connection-created\" | \"connection-removed\" | \"connection-recolored\"", text: { sv: "Byter ut guiden som ett steg som går att ångra, till skillnad från att sätta graph. Guiden migreras först, och sedan skickas graph-changed med { graph, reason }. Används av editorn själv vid import och återställning.", en: "Replaces the guide as an undoable step, unlike setting graph. The guide is migrated first, then graph-changed fires with { graph, reason }. The editor itself uses it for import and reset." } },
      { name: "revealNode", kind: "method", signature: "revealNode(nodeId: string, fieldId?: string): void", text: { sv: "Markerar noden och centrerar den i vyn. Med fieldId öppnas även sidopanelen på Egenskaper och fokus flyttas till det fältet. För en värd som listar problem, t.ex. vad som hindrar publicering, och vill leda redaktören dit.", en: "Selects the node and centres it in view. With fieldId, the side panel also opens on Properties and focus moves to that field. For a host that lists problems, such as what blocks publishing, and wants to take the person editing there." } },
      { name: "setTheme", kind: "method", signature: "setTheme(theme: ThemeChoice | null): void", values: "\"light\" | \"dark\" | null", text: { sv: "Sätter editorns tema; samma som att tilldela egenskapen theme. Editorn har ingen egen temaknapp — värden bygger reglaget i sitt gränssnitt och anropar den här.", en: "Sets the editor's theme; the same as assigning the theme property. The editor has no theme button of its own — the host builds the control in its interface and calls this." } },
      { name: "showToast", kind: "method", signature: "showToast(options: ToastOptions): void  // { message: string; type: \"success\" | \"error\" | \"info\"; duration?: number }", text: { sv: "Visar ett kort meddelande i editorns egen meddelanderuta, t.ex. att guiden sparats. Värden skriver texten själv; den översätts inte.", en: "Shows a short message in the editor's own toast, for example that the guide was saved. The host supplies the text; it is not translated." } },
      { name: "startTour", kind: "method", signature: "startTour(): void", text: { sv: "Startar editorns stegvisa rundtur som pekar ut dess delar. Samma rundtur som redaktören kan starta själv.", en: "Starts the editor's step-by-step tour pointing out its parts. The same tour the person editing can start themselves." } },
      { name: "theme", kind: "property", signature: "theme: \"light\" | \"dark\" | null", values: "\"light\" | \"dark\" | null", text: { sv: "Editorns tema, satt på elementet så att värdens sida inte påverkas. Attributet theme sätter egenskapen, men egenskapen skriver inte tillbaka attributet. Biblioteket sparar inte valet och editorn skickar ingen händelse när egenskapen sätts.", en: "The editor's theme, applied to the element so the host page is unaffected. The theme attribute sets the property, but the property does not write the attribute back. The library does not store the choice, and the editor fires no event when the property is set." } },
      { name: "undo", kind: "method", signature: "undo(): void", text: { sv: "Ångrar det senaste steget, om det finns något. Pågående skrivning räknas som ett steg först. Samma som redaktörens Ångra.", en: "Undoes the last step, if there is one. Typing in progress is recorded as a step first. Same as the person editing choosing Undo." } },
      { name: "unsupportedNodeTypes", kind: "method", signature: "unsupportedNodeTypes(graph?: GraphData): string[]", text: { sv: "Vilka nodtyper i en guide som editorns nuvarande funktioner inte erbjuder, som typnamn. Utan argument gäller det den öppna guiden; med argument kan värden fråga innan en import, t.ex. för att höja nivån först.", en: "Which node types in a guide the editor's current capabilities do not offer, as type names. Without an argument it checks the open guide; with one the host can ask before importing, for example to raise the level first." } },
      { name: "updateCustomNodeType", kind: "method", signature: "updateCustomNodeType(type: string, changes: { label: string; icon?: string }): void", text: { sv: "Byter namn och ikon på en nodmall i biblioteket. Ändringen syns överallt där mallen används, och node-templates-changed skickas. Ikonen tas bort om den utelämnas.", en: "Renames a node template in the library and sets its icon. The change shows everywhere the template is used, and node-templates-changed fires. Omitting icon removes it." } },
    ],
  },
  {
    id: "guide-versions",
    heading: {"sv": "<guide-versions> — versionslistan", "en": "<guide-versions> — the version list"},
    intro: {"sv": "Listan över en guides versioner. Den visar och frågar; att spara, publicera och ta bort gör värden när listan skickar sina avsiktshändelser.", "en": "The list of a guide's versions. It shows and asks; storing, publishing and deleting are the host's, when the list sends its intent events."},
    entries: [
      { name: "editor-locale", kind: "attribute", signature: "editor-locale=\"sv\"", text: { sv: "Språket listans knappar, rubriker och datum skrivs på. Saknas attributet används källspråket.", en: "The language of the list's own buttons, headings and dates. Without it the source language is used." } },
      { name: "order", kind: "attribute", signature: "order=\"saved\" | \"label\" | \"custom\"", text: { sv: "Hur raderna visas. saved och label sorterar en kopia och ändrar ingenting hos värden; custom visar listan exakt som värden lämnade den. Andra värden ignoreras.", en: "How the rows are shown. saved and label sort a copy and change nothing on the host's side; custom shows the array exactly as the host handed it. Other values are ignored." } },
      { name: "theme", kind: "attribute", signature: "theme=\"light\" | \"dark\"", text: { sv: "Ljust eller mörkt tema för just det här elementet, samma ord som på <guide-editor>. Färgar aldrig om sidan runt omkring, och biblioteket minns inte valet.", en: "Light or dark theme for this element only, in the same words as <guide-editor>. It never recolours the page around it, and the library does not remember the choice." } },
      { name: "actions", kind: "property", signature: "actions: VersionAction[] | null  // \"open\" | \"restore\" | \"activate\" | \"save\" | \"discard\" | \"duplicate\" | \"rename\" | \"note\" | \"delete\"", text: { sv: "Vilka handlingar värdens lagring faktiskt kan utföra; bara de knapparna visas. null (standard) visar alla utom restore, som bara visas när den står uttryckligen i listan. Att öppna en rad genom att klicka på den styrs inte av actions.", en: "Which actions the host's storage can actually carry out; only those buttons are shown. null (the default) shows all of them except restore, which appears only when listed explicitly. Opening a row by clicking it is not governed by actions." } },
      { name: "editorLocale", kind: "property", signature: "readonly editorLocale: string | undefined", text: { sv: "Läser attributet editor-locale. Det finns ingen setter; sätt språket med attributet.", en: "Reads the editor-locale attribute. There is no setter; set the language through the attribute." } },
      { name: "order", kind: "property", signature: "order: \"saved\" | \"label\" | \"custom\"", text: { sv: "Samma sak som attributet order, som egenskap. När redaktören drar en rad byter elementet självt till custom.", en: "The same as the order attribute, as a property. When the person editing drags a row, the element switches itself to custom." } },
      { name: "setTheme", kind: "method", signature: "setTheme(theme: \"light\" | \"dark\" | null): void", text: { sv: "Sätter temat; null lämnar tillbaka avgörandet till operativsystemet. Samma som att sätta egenskapen theme.", en: "Sets the theme; null hands the decision back to the operating system. The same as setting the theme property." } },
      { name: "theme", kind: "property", signature: "theme: \"light\" | \"dark\" | null", text: { sv: "Temat som egenskap. Skrivs till data-fw-theme på elementet, inte på dokumentet.", en: "The theme as a property. It is written to data-fw-theme on the element, not on the document." } },
      { name: "versions", kind: "property", signature: "versions: GuideVersion[]  // { id, number?, label?, note?, savedAt?, by?: { subject?, name?, me? }, reason?: \"conflict\", current?, open?, draft?, missing? }", text: { sv: "Versionerna som ska visas, så som värden beskriver dem. Att sätta egenskapen ritar om listan; det är det enda sättet att ändra den. Listan numrerar ingenting själv: number är värdens.", en: "The versions to show, as the host describes them. Setting the property redraws the list; it is the only way to change it. The list never counts on its own: number is the host's." } },
    ],
  },
  {
    id: "prompt-dialog",
    heading: {"sv": "<prompt-dialog> — frågedialogen", "en": "<prompt-dialog> — the prompt dialog"},
    intro: {"sv": "Den dialog editorn och versionslistan frågar med. En värd kan använda samma dialog för sina egna frågor.", "en": "The dialog the editor and the version list ask with. A host can use the same dialog for its own questions."},
    entries: [
      { name: "ask", kind: "method", signature: "ask(options: { title: string; label: string; message?: string; value?: string; placeholder?: string; confirmLabel: string; cancelLabel?: string }): Promise<string | null>", text: { sv: "Öppnar en modal dialog med ett textfält och löser löftet med den inskrivna texten, trimmad. Avbryt, Escape eller ett tomt fält ger null. En ny fråga medan en är öppen avbryter den förra.", en: "Opens a modal dialog with a text field and resolves with what was typed, trimmed. Cancel, Escape or an empty field resolves null. Asking again while one is open cancels the earlier question." } },
      { name: "choose", kind: "method", signature: "choose(options: { title: string; message?: string; choices: Array<{ id: string; label: string }>; cancelLabel?: string }): Promise<string | null>", text: { sv: "Samma dialog men med en knapp per svarsalternativ i stället för ett fält. Löser med valt id, eller null om personen avbryter.", en: "The same dialog with one button per choice instead of a field. Resolves with the chosen id, or null if the person backs out." } },
      { name: "editorLocale", kind: "property", signature: "set editorLocale(value: string)", text: { sv: "Verktygets språk. Påverkar bara standardtexten på Avbryt-knappen; alla andra texter skickar värden in i ask() och choose(). Endast setter, inget attribut.", en: "The tool's language. It only affects the default text of the Cancel button; every other text is passed in by the host through ask() and choose(). Setter only, no attribute." } },
    ],
  },
  {
    id: "events",
    heading: {"sv": "Händelser", "en": "Events"},
    intro: {"sv": "Det elementen berättar för värden. Alla är CustomEvent; detail beskrivs per händelse.", "en": "What the elements tell the host. All are CustomEvents; the detail is described per event."},
    entries: [
      { name: "graph-changed", kind: "event", signature: "CustomEvent<{ graph: GraphData; reason: \"node-moved\" | \"node-nudged\" | \"node-created\" | \"node-removed\" | \"start-node-changed\" | \"node-updated\" | \"node-template-changed\" | \"guide-updated\" | \"graph-imported\" | \"form-skeleton-added\" | \"graph-reset\" | \"connection-created\" | \"connection-removed\" | \"connection-recolored\" }>  // bubbles, composed", element: "guide-editor", text: { sv: "Guiden har ändrats; detail.graph är hela guiden i standardformat och reason säger varför. Kommer vid varje tangenttryckning i ett fält (reason node-updated), så en värd som sparar bör vänta en stund innan den skriver. Det är den här händelsen init() lyssnar på för onSave.", en: "The guide changed; detail.graph is the whole guide in the standard format and reason says why. It fires on every keystroke in a field (reason node-updated), so a host that saves should debounce its writes. This is the event init() listens to for onSave." } },
      { name: "graph-reset-request", kind: "event", signature: "CustomEvent<null>  // no detail; bubbles, composed", element: "guide-editor", text: { sv: "Redaktören har valt att börja om och bekräftat det i editorns varningsdialog. Editorn ändrar ingenting själv: värden avgör vad en tom eller ursprunglig guide är och lämnar den med replaceGraph(graph, \"graph-reset\").", en: "The person editing chose to start over and confirmed it in the editor's warning dialog. The editor changes nothing itself: the host decides what an empty or original guide is and hands it over with replaceGraph(graph, \"graph-reset\")." } },
      { name: "guide-progress", kind: "event", signature: "CustomEvent<{ kind: \"start\" | \"next\" | \"back\" | \"result\" | \"restart\" | \"submitted\" | \"validation-stopped\"; nodeId: string | null; nodeType: string | null; step: number }>  // bubbles, composed", element: "guide-preview", text: { sv: "Besökarens väg genom guiden, för statistik: start, framåt, bakåt, nått ett resultat, börjat om, stoppats av validering, och (i PRO) skickat in. Innehåller aldrig svar. Tyst i editorns förhandsvisning och provkörning (attributen editor-view och proving).", en: "The visitor's way through the guide, for analytics: start, next, back, reached a result, restarted, stopped by validation and (in PRO) submitted. It never carries answers. Silent in the editor's preview and test runs (the editor-view and proving attributes)." } },
      { name: "node-templates-changed", kind: "event", signature: "CustomEvent<{ templates: NodeTemplate[] }>  // bubbles, composed", element: "guide-editor", text: { sv: "Nodmallbiblioteket har ändrats, och detail.templates är hela listan. Biblioteket lagrar ingenting; värden avgör om listan ska sparas och lämnar tillbaka den via nodeTemplates nästa gång. init() kopplar den till onTemplatesChange.", en: "The node template library changed, and detail.templates is the whole list. The library stores nothing; the host decides whether to save it and hands it back through nodeTemplates next time. init() wires it to onTemplatesChange." } },
      { name: "palette-open-changed", kind: "event", signature: "CustomEvent<{ open: boolean }>  // bubbles, composed", element: "guide-editor (raised by its inner <node-palette>, or by the editor itself when it folds the palette to make room)", text: { sv: "Nodpaletten har öppnats eller fällts ihop. En vy, ingen ändring av guiden. Värden kan minnas läget och sätta paletteOpen innan editorn ritas nästa gång.", en: "The node palette was opened or folded. A view, not a change to the guide. The host may remember it and set paletteOpen before the editor is next drawn." } },
      { name: "panel-open-changed", kind: "event", signature: "CustomEvent<{ open: boolean }>  // bubbles, composed", element: "guide-editor", text: { sv: "Sidopanelen har öppnats eller fällts ihop av redaktören eller av editorn. Biblioteket minns det inte; värden kan spara det och sätta panelOpen innan editorn ritas nästa gång.", en: "The side panel was opened or folded, by the person editing or by the editor. The library does not remember it; the host may store it and set panelOpen before the editor is next drawn." } },
      { name: "panel-width-changed", kind: "event", signature: "CustomEvent<{ width: number | null }>  // bubbles, composed", element: "guide-editor", text: { sv: "Redaktören har dragit eller stegat sidopanelens kant färdigt; width är bredden i px som begärdes, null efter återställning. Värden kan spara den och lämna tillbaka den via panelWidth.", en: "The person editing finished dragging or stepping the side panel's edge; width is the requested width in px, null after a reset. The host may store it and hand it back through panelWidth." } },
      { name: "preview-draft-changed", kind: "event", signature: "CustomEvent<{ values: Answers }>  // bubbles, composed", element: "guide-preview", text: { sv: "Det som just nu är inskrivet på en sida som inte skickats vidare än, vid varje tangenttryckning. Främst internt: editorn använder det för att visa samma halvifyllda sida i båda förhandsvisningarna. Skickas bara på steg av typen page.", en: "What is currently typed on a page that has not been submitted yet, per keystroke. Mainly internal: the editor uses it to show the same half-filled page in both previews. Only raised on steps of type page." } },
      { name: "preview-node-changed", kind: "event", signature: "CustomEvent<{ nodeId: string; answers: Answers }>  // bubbles, composed", element: "guide-preview", text: { sv: "Besökaren har gått till ett nytt steg, framåt eller bakåt; detail har stegets id och alla svar hittills. Guiden har ingen egen inlämning, så det är här värden ser att ett resultat har nåtts. Skickas också i editorns förhandsvisning.", en: "The visitor moved to a new step, forwards or back; detail holds the step's id and all answers so far. A guide has no submit of its own, so this is where the host sees that a result was reached. Also raised in the editor's previews." } },
      { name: "save-request", kind: "event", signature: "CustomEvent<null>  // no detail; bubbles, composed, cancelable", element: "guide-editor", text: { sv: "Redaktören bad om att spara (Ctrl+S eller Arkiv → Spara). Värden som sparar anropar preventDefault() och läser guiden med getData(). Om ingen gör det visar editorn ett meddelande om att sidan själv sköter sparandet.", en: "The person editing asked to save (Ctrl+S or File → Save). A host that saves calls preventDefault() and reads the guide with getData(). If nobody does, the editor shows a notice that the page handles saving on its own." } },
      { name: "theme-change", kind: "event", signature: "CustomEvent<{ theme: \"light\" | \"dark\" }>  // bubbles, composed", element: "none of the shipped elements; raised by whoever toggles the theme via announceThemeChange (in this repo: the example site's <theme-toggle>)", text: { sv: "Säger att temat har bytts, så att värden kan minnas valet. Biblioteket sparar inget tema själv. Lyssna på document.", en: "Announces that the theme was switched, so the host can remember the choice. The library stores no theme itself. Listen on document." } },
      { name: "version-activate-intent", kind: "event", signature: "CustomEvent<{ version: GuideVersion }>  // bubbles, composed", element: "guide-versions", text: { sv: "Redaktören vill att den här versionen ska vara den besökarna ser (knappen på raden, för rader som inte är aktuella, saknade eller utkast). Listan ändrar inget; värden gör versionen skarp och skickar sedan en ny versions-lista.", en: "The person editing wants this version to be the one visitors see (the row's button, on rows that are not current, missing or a draft). The list changes nothing; the host makes it live and then sends a new versions array." } },
      { name: "version-delete-intent", kind: "event", signature: "CustomEvent<{ version: GuideVersion }>  // bubbles, composed", element: "guide-versions", text: { sv: "Redaktören vill ta bort versionen. Listan bekräftar inte, eftersom bara värden vet om det går att ångra; fråga själv om det behövs. Knappen finns på alla rader men skickar inget på den aktuella versionen så länge den finns kvar.", en: "The person editing wants to remove the version. The list does not confirm, because only the host knows whether it can be undone; ask yourself if needed. The button is on every row but raises nothing on the current version while it still exists." } },
      { name: "version-discard-intent", kind: "event", signature: "CustomEvent<{ version: GuideVersion }>  // bubbles, composed", element: "guide-versions", text: { sv: "Redaktören vill kasta osparade ändringar. Visas bara på en rad med draft: true. Värden kastar utkastet och lämnar tillbaka versionens innehåll till editorn.", en: "The person editing wants to throw away unsaved changes. Shown only on a row with draft: true. The host drops the draft and gives the version's content back to the editor." } },
      { name: "version-duplicate-intent", kind: "event", signature: "CustomEvent<{ version: GuideVersion }>  // bubbles, composed", element: "guide-versions", text: { sv: "Redaktören vill kopiera versionen. Är radens huvudknapp på den aktuella versionen, annars ett menyval. Värden gör kopian och skickar en ny lista.", en: "The person editing wants a copy of the version. It is the row's main button on the current version and a menu item elsewhere. The host makes the copy and sends a new list." } },
      { name: "version-note-intent", kind: "event", signature: "CustomEvent<{ version: GuideVersion }>  // bubbles, composed", element: "guide-versions", text: { sv: "Redaktören vill skriva vad versionen är. Händelsen bär ingen text; värden frågar själv, till exempel med <prompt-dialog>.ask(), sparar anteckningen och skickar en ny lista.", en: "The person editing wants to say what this version is. The event carries no text; the host asks itself, for example with <prompt-dialog>.ask(), stores the note and sends a new list." } },
      { name: "version-open-intent", kind: "event", signature: "CustomEvent<{ version: GuideVersion }>  // bubbles, composed", element: "guide-versions", text: { sv: "Redaktören vill se den här versionen: ett klick på raden eller namnet. Öppna flyttar och ändrar ingenting; värden läser in versionen i editorn. Styrs inte av actions och skickas inte för en saknad version.", en: "The person editing wants to look at this version: a click on the row or its name. Opening moves and changes nothing; the host loads the version into the editor. Not governed by actions, and not raised for a missing version." } },
      { name: "version-rename-intent", kind: "event", signature: "CustomEvent<{ version: GuideVersion }>  // bubbles, composed", element: "guide-versions", text: { sv: "Redaktören vill byta namn på versionen. Händelsen bär inget nytt namn; värden frågar efter det själv, sparar det och skickar en ny lista.", en: "The person editing wants to rename the version. The event carries no new name; the host asks for it itself, stores it and sends a new list." } },
      { name: "version-reorder-intent", kind: "event", signature: "CustomEvent<{ order: string[] }>  // version ids in the new order; bubbles, composed", element: "guide-versions", text: { sv: "Redaktören har dragit en rad (greppet, eller Alt+pil) till en egen ordning. Elementet byter självt till order custom; värden sparar ordningen om den vill och skickar listan i den ordningen.", en: "The person editing dragged a row (the grip, or Alt+arrow) into an order of their own. The element switches itself to order custom; the host stores the order if it wants and sends the list back in that order." } },
      { name: "version-restore-intent", kind: "event", signature: "CustomEvent<{ version: GuideVersion }>  // bubbles, composed", element: "guide-versions", text: { sv: "Redaktören vill fortsätta arbeta från en äldre version. Knappen visas bara om värden uttryckligen har \"restore\" i actions, och aldrig på den aktuella eller en saknad version. Värden lägger versionens innehåll i editorn som nytt arbete.", en: "The person editing wants to carry on from an older version. The button appears only when the host explicitly lists \"restore\" in actions, and never on the current or a missing version. The host puts that version's content into the editor as new work." } },
      { name: "version-save-intent", kind: "event", signature: "CustomEvent<{ version: GuideVersion }>  // bubbles, composed", element: "guide-versions", text: { sv: "Redaktören vill spara osparat arbete i den här versionen. Visas som radens huvudknapp bara på en rad med draft: true. Värden skriver editorns innehåll (getData()) till versionen och skickar en ny lista.", en: "The person editing wants to save unsaved work into this version. It is the row's main button, only on a row with draft: true. The host writes the editor's content (getData()) into the version and sends a new list." } },
    ],
  },
  {
    id: "viewer-exports",
    heading: {"sv": "Det paketet exporterar — visaren", "en": "What the package exports — the viewer"},
    intro: {"sv": "Funktionerna och typerna i flowweaver-viewer (och därmed i alla bundlar): uppsättning, språk, kodlistor, kartor, färgskalor och svaren.", "en": "The functions and types in flowweaver-viewer (and so in every bundle): setup, languages, code lists, maps, palettes and the answers."},
    entries: [
      { name: "AnswerFields", kind: "type", signature: "type AnswerFields = Record<string, string>", text: { sv: "Delarna i ett svar som har delar, t.ex. etiketten besökaren såg och koden bakom den.", en: "The parts of an answer that has parts, e.g. the label the visitor saw and the code behind it." } },
      { name: "AnswerValue", kind: "type", signature: "type AnswerValue = string | AnswerFields | string[] | AnswerRecord[]", contract: "docs/INLAMNING-KONTRAKT.md", text: { sv: "Ett svar: ett värde, ett värde med delar, flera värden, eller flera poster med delar. Läs det med answerText, answerList eller answerField i stället för String().", en: "One answer: a value, a value with parts, several values, or several records with parts. Read it with answerText, answerList or answerField rather than String()." } },
      { name: "Answers", kind: "type", signature: "type Answers = Record<string, AnswerValue>", text: { sv: "Alla svar i en guide, nycklade på variabelnamn.", en: "Every answer in a guide, keyed by variable name." } },
      { name: "answerText", kind: "function", signature: "answerText(value: AnswerValue | undefined): string", contract: "docs/INLAMNING-KONTRAKT.md", text: { sv: "Gör ett svar till en rad text för en resultattext, ett brev eller en kvittens. Flera värden skiljs med \", \", ett svar med delar visas med sin etikett (label), och ett saknat svar ger \"\".", en: "Turns an answer into one line of text for a result, a letter or a receipt. Several values are joined with \", \", an answer with parts shows its label, and a missing answer gives \"\"." } },
      { name: "answerList", kind: "function", signature: "answerList(value: AnswerValue | undefined): string[]", contract: "docs/INLAMNING-KONTRAKT.md", text: { sv: "Gör ett svar till en lista med jämförbara strängar, för när värden ska testa om svaret innehåller något. Objekt läses på sin etikett (label), tomma poster tas bort, och en äldre radbruten sträng delas upp.", en: "Turns an answer into a list of comparable strings, for when the host checks whether the answer contains something. Objects are read by their label, empty entries are dropped, and an older newline-separated string is split." } },
      { name: "answerField", kind: "function", signature: "answerField(value: AnswerValue | undefined, field: string): string[]", contract: "docs/INLAMNING-KONTRAKT.md", text: { sv: "Plockar ut en del ur varje objekt i ett svar, t.ex. koden (\"value\") för varje valt land. Ger en tom lista för ett svar utan delar; objekt som saknar delen hoppas över.", en: "Picks one part out of each object in an answer, e.g. the code (\"value\") of every chosen country. Returns an empty list for an answer without parts; objects lacking the part are skipped." } },
      { name: "isAnswerEmpty", kind: "function", signature: "isAnswerEmpty(value: AnswerValue | undefined): boolean", text: { sv: "Sant när svaret saknas, är en tom eller blank sträng, en tom lista, eller ett objekt utan etikett.", en: "True when the answer is missing, an empty or blank string, an empty list, or an object without a label." } },
      { name: "type * from ../viewer/types/graph", kind: "type", signature: "export type * from \"../viewer/types/graph\"  // GraphData, FlowNodeData, Connection, GuideSettings, GuideMeta, …", contract: "docs/JSON-KONTRAKT.md", text: { sv: "Typerna för guidens standardformat: GraphData (startnod, noder, kopplingar, inställningar, meta) och allt den består av. Det är formen värden lagrar och sätter som graph på elementet.", en: "The types of the guide's file format: GraphData (start node, nodes, connections, settings, meta) and everything it is made of. This is the shape the host stores and sets as graph on the element." } },
      { name: "SubmissionSchemaProperty", kind: "type", signature: "interface SubmissionSchemaProperty { type: \"string\" | \"number\" | \"boolean\" | \"object\" | \"array\"; label?; format?; pattern?; enum?; options?; kind?; properties?; items?; minItems?; maxItems?; optional? }", contract: "docs/INLAMNING-KONTRAKT.md", text: { sv: "Ett fält i inlämningsschemat: JSON Schema-ord där sådana finns, plus egna (label, options, kind, optional).", en: "One field in the submission schema: JSON Schema keywords where they exist, plus our own (label, options, kind, optional)." } },
      { name: "SubmissionSchema", kind: "type", signature: "interface SubmissionSchema { $guide?: LocalizedTextMap; $serviceId?: string; exportedAt?: string; properties: Record<string, SubmissionSchemaProperty> }", contract: "docs/INLAMNING-KONTRAKT.md", text: { sv: "Formen på det en guide skickar in, som editorn stämplar i meta.submissionSchema vid export, så att en mottagare kan bygga mot den innan första ärendet kommit.", en: "The shape of what a guide submits, stamped by the editor into meta.submissionSchema on export, so a receiver can build against it before the first submission arrives." } },
      { name: "GuidePreview", kind: "class", signature: "class GuidePreview extends HTMLElement  // <guide-preview>", contract: "docs/VARDSYSTEM-KONTRAKT.md", text: { sv: "Klassen bakom <guide-preview>, elementet som kör en färdig guide för besökaren. Elementet registreras när visarpaketet laddas; exporten behövs för typning eller instanceof.", en: "The class behind <guide-preview>, the element that runs a finished guide for the visitor. The element is registered when the viewer bundle loads; the export is for typing or instanceof." } },
      { name: "LanguagePack", kind: "type", signature: "interface LanguagePack { viewer?: Record<string, string>; editor?: Record<string, string> }", text: { sv: "Texterna för ett språk till init, uppdelade på det besökaren läser (viewer) och det redaktören läser (editor).", en: "The texts for one language passed to init, split into what the visitor reads (viewer) and what the person editing reads (editor)." } },
      { name: "LanguageSetup", kind: "type", signature: "interface LanguageSetup { offer?: readonly string[]; source?: string; content?: string; tool?: string }", text: { sv: "Språkdelen av init: vilka språk en guide får erbjudas, vilket en ny guide skrivs på, vilket innehållsspråk som visas, och verktygets eget språk.", en: "The language part of init: which languages a guide may be offered in, which a new guide is written in, which content language is shown, and the tool's own language." } },
      { name: "HostSetup", kind: "type", signature: "interface HostSetup { graph?; mode?; languages?; packs?; templates?; versions?; theme?; onSave?; onTemplatesChange? }", contract: "docs/VARDSYSTEM-KONTRAKT.md", text: { sv: "Allt värden ger init: guiden, behörighetsläget, språken, språkpaket, nodmallar, versioner, tema och återanropen för att spara.", en: "Everything the host passes to init: the guide, the permission mode, languages, language packs, node templates, versions, theme and the save callbacks." } },
      { name: "Wiring", kind: "type", signature: "interface Wiring { coverage: Record<string, LocaleCoverage>; disconnect: () => void }", text: { sv: "Det init returnerar: täckningen för varje registrerat språkpaket och en funktion som slutar lyssna.", en: "What init returns: the coverage of each registered language pack and a function that stops listening." } },
      { name: "init", kind: "function", signature: "init(element: HTMLElement, setup?: HostSetup): Wiring", contract: "docs/VARDSYSTEM-KONTRAKT.md", text: { sv: "Kopplar in ett element i värden med ett anrop: registrerar språkpaket först, deklarerar språken, sätter mode, editor-locale, active-locale, tema, versioner och mallar, lyssnar efter ändringar till onSave/onTemplatesChange och sätter guiden sist. Returnerar paketens täckning och disconnect(). Gjord för <guide-editor>; på <guide-preview> gäller språk, tema och guide, medan onSave aldrig anropas eftersom visaren inte skickar graph-changed.", en: "Wires an element into the host in one call: registers language packs first, declares the languages, sets mode, editor-locale, active-locale, theme, versions and templates, listens for changes to call onSave/onTemplatesChange, and sets the guide last. Returns the packs' coverage and disconnect(). Built for <guide-editor>; on <guide-preview> the languages, theme and guide apply, while onSave never fires because the viewer does not emit graph-changed." } },
      { name: "SetupSeverity", kind: "type", signature: "type SetupSeverity = \"error\" | \"warning\"", text: { sv: "Hur allvarligt ett fynd från checkSetup är.", en: "How serious a checkSetup finding is." } },
      { name: "SetupFinding", kind: "type", signature: "interface SetupFinding { id: string; severity: SetupSeverity; what: string; consequence: string }", text: { sv: "Ett fynd från checkSetup: ett stabilt id att filtrera på, allvar, vad som observerats och vad det leder till (på engelska).", en: "One checkSetup finding: a stable id to filter on, severity, what was observed and what it leads to (in English)." } },
      { name: "SetupReport", kind: "type", signature: "interface SetupReport { ok: boolean; findings: SetupFinding[] }", text: { sv: "Svaret från checkSetup; ok är sant bara när inget hittades.", en: "The answer from checkSetup; ok is true only when nothing was found." } },
      { name: "CheckableElement", kind: "type", signature: "interface CheckableElement extends HTMLElement { graph?: GraphData }", text: { sv: "Elementet checkSetup granskar: <guide-preview> eller <guide-editor>.", en: "The element checkSetup inspects: <guide-preview> or <guide-editor>." } },
      { name: "checkSetup", kind: "function", signature: "checkSetup(element: CheckableElement): SetupReport", contract: "docs/VARDSYSTEM-KONTRAKT.md", text: { sv: "Granskar ett monterat elements uppsättning och rapporterar på engelska: tokens som inte löser ut, <guide-editor> utan mode, och språk guiden erbjuder som saknar visartexter eller står utanför declareLocales. Säger inget om lagring eller lyssnare, så ok: true betyder bara att inget av detta hittades. Anropa efter montering, när guiden är satt.", en: "Inspects a mounted element's setup and reports in English: tokens that do not resolve, a <guide-editor> without mode, and languages the guide offers that lack viewer texts or fall outside declareLocales. It says nothing about storage or listeners, so ok: true means only that none of these was found. Call it after mounting, once the guide is set." } },
      { name: "LocaleStrings", kind: "type", signature: "type LocaleStrings = Readonly<Record<string, string>>", text: { sv: "Ett språkpaket: textnycklar mot texter.", en: "A language pack: text keys mapped to texts." } },
      { name: "registerLocale", kind: "function", signature: "registerLocale(locale: string, strings: LocaleStrings): LocaleCoverage", contract: "docs/VARDSYSTEM-KONTRAKT.md", text: { sv: "Registrerar visarens texter för ett språk, t.ex. arabiska knappar eller en egen svensk formulering. Ett nytt anrop för samma språk ersätter paketet. Returnerar hur mycket paketet täcker. Anropa vid start, innan elementen ritas.", en: "Registers the viewer's texts for one language, e.g. Arabic buttons or the host's own Swedish wording. Calling again for the same language replaces the pack. Returns how much the pack covers. Call it at startup, before the elements render." } },
      { name: "unregisterLocale", kind: "function", signature: "unregisterLocale(locale: string): void", text: { sv: "Tar bort ett registrerat språkpaket.", en: "Removes a registered language pack." } },
      { name: "localeStrings", kind: "function", signature: "localeStrings(locale: string): Record<string, string>", text: { sv: "Ger alla texter för ett språk som en platt mall att översätta från: paketets egna, med värdens registrerade texter före.", en: "Returns every text for one language as a flat template to translate from: the package's own, overridden by the host's registered texts." } },
      { name: "builtInLocales", kind: "function", signature: "builtInLocales(): string[]", text: { sv: "Språkkoderna paketet har egna texter för, sorterade.", en: "The language codes the package ships its own texts for, sorted." } },
      { name: "availableLocales", kind: "function", signature: "availableLocales(): string[]", text: { sv: "Språkkoderna visaren kan visas på: paketets egna plus de värden registrerat, sorterade.", en: "The language codes the viewer can be shown in: the package's own plus those the host registered, sorted." } },
      { name: "AudienceCoverage", kind: "type", signature: "interface AudienceCoverage { filled: number; total: number; missing: string[] }", text: { sv: "Hur många nycklar ett språk täcker för en målgrupp, och vilka som saknas.", en: "How many keys a language covers for one audience, and which are missing." } },
      { name: "LocaleCoverage", kind: "type", signature: "interface LocaleCoverage { locale: string; viewer: AudienceCoverage; editor: AudienceCoverage }", text: { sv: "Ett språks täckning, separat för visarens och editorns texter.", en: "A language's coverage, separately for the viewer's and the editor's texts." } },
      { name: "coverageOf", kind: "function", signature: "coverageOf(locale: string): LocaleCoverage", text: { sv: "Rapporterar hur mycket av visarens och editorns texter ett språk täcker, räknat på registrerade och inbyggda texter. Med bara visaren laddad blir editorsidan 0 av 0.", en: "Reports how much of the viewer's and the editor's texts a language covers, counting registered and built-in texts. With only the viewer loaded the editor side reads 0 of 0." } },
      { name: "LocaleDeclaration", kind: "type", signature: "interface LocaleDeclaration { default?: string }", text: { sv: "Alternativet till declareLocales: vilket språk som är standard.", en: "The option to declareLocales: which language is the default." } },
      { name: "declareLocales", kind: "function", signature: "declareLocales(locales: readonly string[], options?: LocaleDeclaration): void", contract: "docs/VARDSYSTEM-KONTRAKT.md", text: { sv: "Deklarerar vilka språk en guide får erbjudas på och vilket som är standard (annars det första). Ett nytt anrop ersätter deklarationen. Inget skrivs i guiden.", en: "Declares which languages a guide may be offered in and which is the default (otherwise the first). Calling again replaces the declaration. Nothing is written into the guide." } },
      { name: "clearDeclaredLocales", kind: "function", signature: "clearDeclaredLocales(): void", text: { sv: "Tar bort språkdeklarationen, så att declaredLocales åter ger null.", en: "Clears the language declaration, so declaredLocales returns null again." } },
      { name: "declaredLocales", kind: "function", signature: "declaredLocales(): readonly string[] | null", text: { sv: "De deklarerade språken, eller null när värden inte deklarerat några.", en: "The declared languages, or null when the host has declared none." } },
      { name: "declaredDefaultLocale", kind: "function", signature: "declaredDefaultLocale(): string | null", text: { sv: "Det deklarerade standardspråket, eller null.", en: "The declared default language, or null." } },
      { name: "CodeListItem", kind: "type", signature: "interface CodeListItem { value: string; label: LocalizedTextMap; synonyms?: LocalizedTextMap[]; sourceLabel?: string; exclusive?: boolean }", text: { sv: "En post i en kodlista: koden som lagras, etiketten per språk, synonymer att söka på, och om posten utesluter alla andra.", en: "One entry in a code list: the stored code, its label per language, synonyms to search by, and whether it excludes every other entry." } },
      { name: "CodeStandard", kind: "type", signature: "type CodeStandard = \"iso-3166-1-alpha-2\" | \"iso-3166-1-alpha-3\" | \"iso-3166-1-numeric\" | \"custom\"", text: { sv: "Vilken standard en kodlistas koder följer.", en: "Which standard a code list's codes follow." } },
      { name: "CodeList", kind: "type", signature: "interface CodeList { id; standard: CodeStandard; label; version; published; source; sourceUrl?; labelSources?; items: CodeListItem[] }", text: { sv: "En kodlista som värden registrerar, med standard, källa och version.", en: "A code list the host registers, with its standard, source and version." } },
      { name: "registerCodeList", kind: "function", signature: "registerCodeList(list: CodeList): void", contract: "docs/VARDSYSTEM-KONTRAKT.md", text: { sv: "Gör en kodlista (t.ex. länder eller kommuner) tillgänglig för fält och regler. Listorna skeppas som standardformat bredvid bundlarna och ingen är inbyggd. Samma id en gång till ersätter den tidigare listan; en felaktig lista avvisas med ett TypeError som säger vad som är fel.", en: "Makes a code list (e.g. countries or municipalities) available to fields and rules. The lists ship as JSON beside the bundles and none is built in. The same id replaces the earlier list; a malformed list is refused with a TypeError saying what is wrong." } },
      { name: "codeListFault", kind: "function", signature: "codeListFault(list: unknown): string | null", text: { sv: "Kontrollerar en kodlista utan att registrera den: returnerar en beskrivning av felet (på svenska), eller null när listan duger.", en: "Checks a code list without registering it: returns a description of the fault (in Swedish), or null when the list is valid." } },
      { name: "unregisterCodeList", kind: "function", signature: "unregisterCodeList(id: string): void", text: { sv: "Tar bort en registrerad kodlista.", en: "Removes a registered code list." } },
      { name: "getCodeList", kind: "function", signature: "getCodeList(id: string): CodeList | null", text: { sv: "Hämtar en registrerad kodlista, eller null.", en: "Returns a registered code list, or null." } },
      { name: "getCodeLists", kind: "function", signature: "getCodeLists(): CodeList[]", text: { sv: "Alla registrerade kodlistor.", en: "Every registered code list." } },
      { name: "MapKind", kind: "type", signature: "type MapKind = \"point\" | \"points\" | \"area\"", contract: "docs/KART-KONTRAKT.md", text: { sv: "Vilken sorts geometri en kartfråga ber om; points och area är enligt koden reserverade för v2.", en: "What kind of geometry a map question asks for; per the code, points and area are reserved for v2." } },
      { name: "MapPickResult", kind: "type", signature: "interface MapPickResult { geometry: { type: string; coordinates: unknown }; label: string; zoom?: number }", contract: "docs/KART-KONTRAKT.md", text: { sv: "Svaret från värdens karta: GeoJSON i WGS84 ([longitud, latitud]), en läsbar etikett och eventuellt zoomnivån.", en: "The answer from the host's map: GeoJSON in WGS84 ([longitude, latitude]), a readable label and optionally the zoom level." } },
      { name: "MapProvider", kind: "type", signature: "interface MapProvider { kinds: readonly MapKind[]; pick(options): Promise<MapPickResult | null>; snapshot?(geometry, options?): Promise<string> }", contract: "docs/KART-KONTRAKT.md", text: { sv: "Värdens karta: vilka sorter den klarar, pick som låter besökaren peka ut geometri (null vid avbrott), och en frivillig stillbild.", en: "The host's map: which kinds it supports, pick which lets the visitor point out geometry (null on cancel), and an optional still image." } },
      { name: "registerMapProvider", kind: "function", signature: "registerMapProvider(next: MapProvider): void", contract: "docs/KART-KONTRAKT.md", text: { sv: "Registrerar värdens kartleverantör, som kartfrågor sedan anropar; FlowWeaver ritar ingen karta själv. Det finns en leverantör åt gången och ett nytt anrop ersätter den.", en: "Registers the host's map provider, which map questions then call; FlowWeaver draws no map itself. There is one provider at a time and a new call replaces it." } },
      { name: "unregisterMapProvider", kind: "function", signature: "unregisterMapProvider(): void", contract: "docs/KART-KONTRAKT.md", text: { sv: "Tar bort den registrerade kartleverantören.", en: "Removes the registered map provider." } },
      { name: "Palette", kind: "type", signature: "interface Palette { id: string; label: string; light: Record<string, string>; dark: Record<string, string> }", text: { sv: "En färdig färgskala: tokenvärden för ljust och mörkt läge.", en: "A finished colour scale: token values for light and dark mode." } },
      { name: "palettes", kind: "constant", signature: "const palettes: { hav: Palette; skog: Palette; skiffer: Palette; tegel: Palette }", text: { sv: "De fyra inbyggda färgskalorna (hav, skog, skiffer, tegel), att ge till applyPalette.", en: "The four built-in colour scales (hav, skog, skiffer, tegel), to pass to applyPalette." } },
      { name: "applyPalette", kind: "function", signature: "applyPalette(palette: Palette | null): void", text: { sv: "Färgar om FlowWeavers element i ett steg genom att lägga en <style> i <head> med skalans hela primärfamilj och nodfärger, för ljust och mörkt läge. null tar bort den och ger tillbaka standardfärgen. Den sätter också --fw-*-tokens på :root.", en: "Recolours FlowWeaver's elements in one step by adding a <style> to <head> with the scale's whole primary family and node colours, for light and dark mode. null removes it and restores the default colour. It also sets the --fw-* tokens on :root." } },
    ],
  },
  {
    id: "editor-exports",
    heading: {"sv": "Det editorn lägger till", "en": "What the editor adds"},
    intro: {"sv": "Det flowweaver-editor exporterar utöver visaren.", "en": "What flowweaver-editor exports on top of the viewer."},
    entries: [
      { name: "GuideEditor", kind: "class", signature: "class GuideEditor extends HTMLElement  // <guide-editor>\n  attributes: feature-level, modules, mode, mode-notice, editor-locale, active-locale, theme, get-started-href, panel-width, panel-open, palette-open, palette-search\n  graph: GraphData; getData(): GraphData; replaceGraph(value, reason); undo(); redo(); setTheme(theme: ThemeChoice | null)\n  events: graph-changed, save-request, locale-change, panel-width-changed, panel-open-changed, palette-open-changed", text: { sv: "Elementet `<guide-editor>`, som registreras när editorpaketet laddas. Värden sätter `graph`, läser tillbaka guiden med `getData()` (stämplad med formatversion) och lyssnar på `graph-changed` och `save-request` för att själv spara — editorn lagrar ingenting.", en: "The `<guide-editor>` element, registered when the editor bundle loads. The host sets `graph`, reads the guide back with `getData()` (stamped with its format version) and listens for `graph-changed` and `save-request` to store it itself; the editor stores nothing." } },
      { name: "GuideVersion", kind: "type", signature: "interface GuideVersion {\n  id: string; number?: number; label?: string; note?: string; savedAt?: number;\n  by?: { subject?: string; name?: string; me?: boolean };\n  reason?: \"conflict\"; current?: boolean; open?: boolean; draft?: boolean; missing?: boolean;\n}", contract: "docs/LAGRING-KONTRAKT.md", text: { sv: "En rad i `<guide-versions>`, som värden beskriver den ur sin egen lagring. `number`, `by` och `reason` är värdens att sätta och räknas aldrig fram i listan; `current` är versionen besökarna ser, `open` den redaktören arbetar i.", en: "One row in `<guide-versions>`, as the host describes it from its own storage. `number`, `by` and `reason` are the host's to set and are never computed by the list; `current` is the version visitors see, `open` the one the person editing is working from." } },
      { name: "GuideVersions", kind: "class", signature: "class GuideVersions extends HTMLElement  // <guide-versions>\n  attributes: editor-locale, order, theme\n  versions: GuideVersion[]; order: VersionOrder; actions: VersionAction[] | null; theme: ThemeChoice | null\n  events: version-{open|restore|activate|save|discard|duplicate|rename|note|delete}-intent { detail: { version } },\n          version-reorder-intent { detail: { order: string[] } }", contract: "docs/LAGRING-KONTRAKT.md", text: { sv: "Elementet `<guide-versions>`: listan över en guides versioner. Den beslutar ingenting — den ritar raderna och skickar `version-*-intent`-händelser; läsa, skriva, namnge och ta bort gör värden. Med `actions` säger värden vilka åtgärder dess lagring klarar, så att menyn bara visar dem.", en: "The `<guide-versions>` element: the list of a guide's versions. It decides nothing — it renders rows and raises `version-*-intent` events; reading, writing, naming and removing stay with the host. With `actions` the host says which actions its storage supports, so the menu shows only those." } },
      { name: "LinkPickContext", kind: "type", signature: "interface LinkPickContext {\n  locale: string;        // language of the text being edited\n  selectedText: string;  // \"\" when nothing was selected\n}", text: { sv: "Det värdens länkväljare får när redaktören trycker på länkknappen: språket på texten som redigeras och den markerade texten.", en: "What the host's link picker receives when the person editing presses the link button: the language of the text being edited and the selected text." } },
      { name: "LinkPickResult", kind: "type", signature: "interface LinkPickResult {\n  url: string;     // the address the viewer renders; relative is fine\n  label?: string;  // link text when nothing was selected\n  ref?: string;    // the host's own reference for the page\n}", text: { sv: "Svaret från värdens länkväljare. Med `ref` skrivs länken `[text](adress \"ref\")`; visaren visar bara adressen, och editorn kan senare fråga `resolve` om sidan flyttats.", en: "The host's link picker's answer. With `ref` the link is written `[text](address \"ref\")`; the viewer renders only the address, and the editor can later ask `resolve` whether the page has moved." } },
      { name: "LinkPicker", kind: "type", signature: "interface LinkPicker {\n  pick(context: LinkPickContext): Promise<LinkPickResult | null>;\n  resolve?(ref: string): Promise<{ url: string } | null>;\n}", text: { sv: "Värdens länkväljare. `pick` öppnar värdens egen dialog och svarar `null` när redaktören avbryter. Valfria `resolve` tillfrågas om varje referens när en guide öppnas i editorn: en ändrad adress skrivs om, `null` (sidan finns inte) blir en hälsovarning, och ett kastat fel räknas som inget svar.", en: "The host's link picker. `pick` opens the host's own dialog and resolves to `null` when the person editing cancels. The optional `resolve` is asked about every reference when a guide is opened in the editor: a changed address is rewritten, `null` (page gone) becomes a health warning, and a thrown error counts as no answer." } },
      { name: "PromptDialog", kind: "class", signature: "class PromptDialog extends HTMLElement  // <prompt-dialog>\n  editorLocale: string (setter)\n  ask(options: PromptOptions): Promise<string | null>\n  choose(options: { title: string; message?: string; choices: Array<{ id: string; label: string }>; cancelLabel?: string }): Promise<string | null>", text: { sv: "Elementet `<prompt-dialog>`, en modal dialog som frågar efter ett ord — till exempel vad en kopia ska heta när `<guide-versions>` skickar `version-rename-intent`. `ask` ger texten, eller `null` vid avbryt eller tomt svar; `choose` erbjuder fasta val i stället för ett fält.", en: "The `<prompt-dialog>` element, a modal dialog that asks for a word — for example what a copy should be called when `<guide-versions>` raises `version-rename-intent`. `ask` resolves to the text, or `null` on cancel or an empty answer; `choose` offers fixed choices instead of a field." } },
      { name: "PromptOptions", kind: "type", signature: "interface PromptOptions {\n  title: string; label: string; message?: string; value?: string;\n  placeholder?: string; confirmLabel: string; cancelLabel?: string;\n}", text: { sv: "Det värden ger `PromptDialog.ask`: rubrik, etikett över fältet, ett valfritt förklarande meddelande, startvärde och knapptexter. Utan `cancelLabel` används editorns egen text för Avbryt.", en: "What the host passes to `PromptDialog.ask`: title, a label above the field, an optional explanatory message, an initial value and button texts. Without `cancelLabel` the editor's own Cancel text is used." } },
      { name: "ThemeChoice", kind: "type", signature: "type ThemeChoice = \"light\" | \"dark\";", text: { sv: "Ljust eller mörkt tema för `theme` på `<guide-editor>` och `<guide-versions>`; `null` betyder att operativsystemets inställning gäller. Temat sätts på elementet, inte på värdens sida, och biblioteket sparar inte valet — att minnas det är värdens sak.", en: "Light or dark theme for `theme` on `<guide-editor>` and `<guide-versions>`; `null` means the operating system's setting applies. The theme is set on the element, not on the host's page, and the library does not store the choice — remembering it is the host's job." } },
      { name: "VersionOrder", kind: "type", signature: "type VersionOrder = \"saved\" | \"label\" | \"custom\";", text: { sv: "Hur `<guide-versions>` ordnar raderna: efter datum, efter namn, eller i den ordning värden lämnade dem (`custom`). Datum och namn är bara en vy; när redaktören drar en rad växlar listan till `custom` och ber värden om den nya ordningen med `version-reorder-intent`.", en: "How `<guide-versions>` orders its rows: by date, by name, or in the order the host handed them (`custom`). Date and name are only a view; when the person editing drags a row, the list switches to `custom` and asks the host for the new order with `version-reorder-intent`." } },
      { name: "registerLinkPicker", kind: "function", signature: "function registerLinkPicker(value: LinkPicker): void", text: { sv: "Registrerar värdens länkväljare, så att editorns länkknapp öppnar värdens dialog i stället för att skriva `[text](https://)`. En ny registrering ersätter den förra och glömmer tidigare `resolve`-svar.", en: "Registers the host's link picker, so the editor's link button opens the host's dialog instead of writing `[text](https://)`. A new registration replaces the previous one and forgets earlier `resolve` answers." } },
      { name: "unregisterLinkPicker", kind: "function", signature: "function unregisterLinkPicker(): void", text: { sv: "Tar bort värdens länkväljare; länkknappen skriver då `[text](https://)` som utan väljare.", en: "Removes the host's link picker; the link button then writes `[text](https://)` as it does without one." } },
    ],
  },
];
